'use strict';
function actionLabel(action){return ({create:()=>txt('新建副本','Create copy'),update:()=>txt('更新副本','Update copy'),remove:()=>txt('移除副本','Remove copy')})[action]?.()||action;}
// Channel-specific capabilities share the same confirmation and task views.
function channelName(id){return channelCatalog.find(c=>c.id===id)?.name||id;}
function taskButton(j){return flowButton('查看任务','View task','open-copy-job',j.id,'sm');}
function exactCopyContent(j){return `<div class="copy-facts">${[['内容归属','Owner',workspaceLabel(j.owner)],['语言与版本','Language & version',`${j.lang.toUpperCase()} · v${j.snapshot.version}`],['目标账号','Account',`${channelName(j.channel)} / ${j.account}`],['动作','Action',actionLabel(j.action)],['内容形式','Format',j.format==='excerpt'?txt('摘要与来源','Excerpt with source'):txt('全文副本','Full copy')],['原文来源','Original source',j.sourceUrl]].map(([a,b,v])=>`<div class="review-line"><span>${txt(a,b)}</span><strong>${esc(v)}</strong></div>`).join('')}</div><details class="body-disclosure copy-details"><summary>${txt('查看本次完整内容','Review the exact content')}</summary><div class="exact-preview" data-i18n-preserve>${renderMarkdown(j.format==='excerpt'?j.excerpt:j.snapshot.savedBody,{article:articles.find(a=>a.id===j.articleId),lang:j.lang})}</div></details>`;}
function channelWorkflowCard(c){const jobs=copyTasks().filter(j=>j.channel===c.id),j=jobs.at(-1),copy=copyFor(c.id),connection=connectionStates[state.workspace][c.id];const supported=connection!=='unsupported',busy=jobs.some(x=>!['published','removed','cancelled','failed','rejected','blocked'].includes(x.status));return `<section class="panel channel-card"><div class="channel-head">${platform(c.id)}<div class="channel-name"><strong>${c.name}</strong><small>${txt(c.id==='dev'?'自动新建 / 更新 · 人工移除':c.id==='hashnode'?'组织 Pro · 自动新建 / 更新 / 移除':'人工投稿与跟进',c.id==='dev'?'Automatic create / update · Manual removal':c.id==='hashnode'?'Organization Pro · Automatic create / update / remove':'Assisted submission & follow-up')}</small></div>${j?statusBadge(j.status):statusBadge(connection)}</div><div class="channel-message ${j?.status==='approval_needed'?'amber':''}"><strong>${txt('指定账号','Designated account')} <span data-i18n-preserve>${esc(connectionMeta[state.workspace][c.id].account)}</span></strong><p>${j?(j.delay?txt('等待稍后由人执行，不会自动发送。','Waiting for a later human action; nothing sends automatically.')+' '+esc(j.delay):txt('每项任务保留确认内容、链接和完整历史。','Each task retains its confirmed content, links and full history.')):txt('先核验连接，再选择全文或摘要并确认本次动作。','Verify the connection, then choose a full copy or excerpt and confirm this action.')}</p></div>${copy?`<p class="copy-link"><a href="${esc(copy.url)}" target="_blank" rel="noopener noreferrer">${esc(copy.url)} ${icon('external')}</a><small>${txt('样例链接 · 非真实发布结果','Sample URL · Not a real publication')} · v${copy.version}</small></p>`:''}<div class="workflow-actions">${flowButton('查看连接','View connection','channel-connect',c.id,'sm quiet')}${j?taskButton(j):''}${!copy&&supported&&!busy?flowButton('安排分发','Arrange distribution','copy-setup',c.id+':create','sm primary'):''}${copy&&!busy?flowButton('纠错现有副本','Correct known copy','copy-setup',c.id+':update:'+copy.id,'sm')+flowButton(c.id==='dev'?'人工移除副本':'移除副本',c.id==='dev'?'Manual copy removal':'Remove copy','copy-setup',c.id+':remove:'+copy.id,'sm'):''}${jobs.length?flowButton('全部记录','All activity','channel-history',c.id,'sm quiet'):''}</div></section>`;}
distributionPage=function(){const a=current(),l=language();return routeButton(txt('全部发布任务','All publication tasks'),'deliveries','quiet','back')+titleBlock('EVERY DESTINATION, ONE VIEW','文章分发详情',txt('原文、渠道与每次动作独立记录。','The original, channels and individual actions are tracked separately.'))+`<section class="panel source-summary">${platform('ghost')}<div><strong data-i18n-preserve>${esc(l.liveSnapshot?.savedTitle||l.savedTitle)}</strong><p>${workspaceLabel()} · ${state.lang.toUpperCase()} · v${l.live||'—'} · ${publicationTarget().host}</p></div>${statusBadge(isPublic(a,state.lang)?'published':l.live?'unpublished':'draft')}</section>${originalTaskCard(latestOriginal())}${!canPublish()?notice(txt('当前身份可阅读公开原文，不能查看组织私有分发任务。','You may read the public original, but cannot access private organization distribution tasks.')):state.lang!=='en'?notice(txt('中文独立发布；外部分发需先验证目标政策与渲染，当前仅开放英文。','Chinese publishes independently. External distribution currently supports English only, pending policy and rendering verification.')):`<div class="distribution-grid"><div class="channel-stack">${!isPublic(a,state.lang)?notice(txt('原文当前不可公开访问。暂停新建和更新副本；已知副本仍可核验和移除。','The original is not public. New copies and updates are paused; known copies can still be verified and removed.')):''}${channelCatalog.map(channelWorkflowCard).join('')}</div><aside class="distribution-aside editor-sidebar"><section class="panel aside-panel"><h2>${txt('发布顺序','Publishing sequence')}</h2><ol class="workflow-steps"><li>${txt('确认原文公开','Verify the public original')}</li><li>${txt('核验指定账号连接','Verify the designated connection')}</li><li>${txt('确认形式、内容与时间','Confirm format, content and timing')}</li><li>${txt('组织自动动作取得精确批准','Obtain exact approval for automatic organization actions')}</li><li>${txt('核验结果，持续跟进','Verify results and follow up')}</li></ol></section>${notice(txt('DEV 移除走人工跟进。恢复连接不会重发任务，未知结果必须先核验。','DEV removal requires manual follow-up. Reconnection never resends tasks; unknown results must be verified first.'))}</aside></div>`}${canPublish()&&l.live?`<div class="original-management"><div><strong>${txt('原文管理','Original management')} · ${state.lang.toUpperCase()}</strong><p>${txt('下线不自动移除副本。','Unpublishing does not remove external copies.')}</p></div>${isPublic(a,state.lang)?btn('下线原文','unpublish','danger'):routeButton('重新确认发布','publish','primary')}</div>`:''}`;};
pageRenderers.distribution=distributionPage;
let copyIntent=null,activeCopyJob=null;
flowHandlers['channel-connect']=id=>showChannel(id);
flowHandlers['copy-setup']=encoded=>{const [channel,action,copyId]=encoded.split(':');if(!canPublish())return flowError('Publishing permission required');if(!canStartCopy(state.workspace,channel)&&!copyId)return showChannel(channel);if(action!=='remove'&&!isPublic(current(),state.lang))return flowError('Verify the public original first');if(state.lang!=='en')return flowError('Only English external distribution is enabled');copyIntent={owner:state.workspace,articleId:state.articleId,lang:state.lang,channel,action,copyId,snapshot:snapshot(language().liveSnapshot),connectionId:connectionMeta[state.workspace][channel].id,account:connectionMeta[state.workspace][channel].account,format:'full',excerpt:'',delay:''};renderCopySetup();};
function renderCopySetup(){const i=copyIntent;if(!i)return;const lost=!canStartCopy(i.owner,i.channel);modal(channelName(i.channel)+' · '+txt('确认分发内容','Confirm distribution'),`<p>${txt('本次动作绑定确定版本及指定账号。','This action is bound to the exact version and designated account.')}</p><div class="review-line"><span>${workspaceLabel(i.owner)} · ${i.lang.toUpperCase()} · v${i.snapshot.version}</span><strong>${actionLabel(i.action)}</strong></div>${lost?notice(txt('原账号连接已失效，只能创建人工跟进记录。','The original account connection is unavailable. Only a manual follow-up record can be created.')):''}${i.action==='remove'?notice(txt(automaticCopyAction(i.channel,i.action)?'将请求移除已知副本，并单独核验结果。':'此渠道需要在平台人工移除，再核验已知链接。',automaticCopyAction(i.channel,i.action)?'Request removal of the known copy, then verify the result.':'Remove the copy manually on the platform, then verify its known URL.')):`<div class="form-field"><label for="copy-format">${txt('分发形式','Copy format')}</label><select id="copy-format"><option value="full" ${i.format==='full'?'selected':''}>${txt('全文副本','Full copy')}</option><option value="excerpt" ${i.format==='excerpt'?'selected':''}>${txt('摘要与来源链接','Excerpt with source link')}</option></select></div><div class="form-field"><label for="copy-excerpt">${txt('摘要正文（选择摘要时必填）','Excerpt content (required for excerpts)')}</label><textarea id="copy-excerpt" rows="4">${esc(i.excerpt)}</textarea></div><div class="form-field"><label for="copy-delay">${txt('稍后执行时间（可选，由人执行）','Later action time (optional; human action required)')}</label><input id="copy-delay" type="datetime-local" value="${esc(i.delay)}"><small>${txt('时间只创建待办，不会自动发送或提前获得批准。','The time creates a reminder, not an automatic send or advance approval.')}</small></div>`}<p class="form-error" id="copy-error" role="alert"></p><div class="review-line"><span>${txt('原文来源','Original source')}</span><span class="mono">${esc(sourceUrl())}</span></div>`,btn('取消','close-modal')+flowButton('预览并确认','Preview & confirm','preview-copy','','primary'),true);}
flowHandlers['preview-copy']=()=>{const i=copyIntent;if(!i||i.owner!==state.workspace||i.articleId!==state.articleId||i.lang!==state.lang)return flowError('The workspace or article changed');i.format=document.getElementById('copy-format')?.value||'full';i.excerpt=document.getElementById('copy-excerpt')?.value||'';i.delay=document.getElementById('copy-delay')?.value||'';if(i.format==='excerpt'&&!i.excerpt.trim()){document.getElementById('copy-error').textContent=txt('请填写摘要正文。','Enter the excerpt content.');return;}if(i.delay&&(!Number.isFinite(Date.parse(i.delay))||Date.parse(i.delay)<=Date.now())){document.getElementById('copy-error').textContent=txt('请选择未来时间。','Choose a future time.');return;}const j={...i,account:connectionMeta[i.owner][i.channel].account,sourceUrl:sourceUrl()};modal(txt('确认此次分发','Confirm this distribution'),exactCopyContent(j)+notice(i.delay?txt('到达计划时间后仍需人工执行。','A human must start this task after the planned time.'):txt('创建任务后，按渠道能力继续批准或人工跟进。','After creating the task, continue with approval or manual follow-up as required.')),flowButton('返回修改','Back to edit','edit-copy')+flowButton('确认并创建任务','Confirm & create task','create-copy','','primary'),true);};
flowHandlers['edit-copy']=()=>renderCopySetup();
flowHandlers['create-copy']=()=>{const i=copyIntent;if(!i||i.owner!==state.workspace||i.articleId!==state.articleId||i.lang!==state.lang||i.snapshot.version!==language().live||i.connectionId!==connectionMeta[i.owner][i.channel].id||i.account!==connectionMeta[i.owner][i.channel].account)return flowError('The original or workspace changed; confirm again');const j=createCopyJob(i.channel,i);if(!j)return flowError('An active task exists or the publishing conditions changed');copyIntent=null;closeModal();render();flowHandlers['open-copy-job'](j.id);};
flowHandlers['open-copy-job']=id=>{const j=copyJobs.find(x=>x.id===id);if(!j||j.owner!==state.workspace||!canPublish())return;activeCopyJob=id;let controls=flowButton('历史','History','copy-history',id,'quiet')+flowButton('下载投稿材料','Download submission package','download-copy',id,'quiet');if(['scheduled','failed','blocked'].includes(j.status))controls+=flowButton('重新核对并继续','Recheck & continue','activate-copy',id);if(j.status==='approval_needed')controls+=flowButton('模拟 Admin 精确批准','Simulate exact Admin approval','approve-copy',id,'primary');if(j.status==='ready')controls+=flowButton('执行已确认动作 · 演示','Run confirmed action · Demo','run-copy',id,'primary');if(j.status==='uncertain')controls+=flowButton('只读核验结果','Verify existing result','verify-copy',id,'primary');if(['manual_action_needed','submitted','reviewing','rejected'].includes(j.status)&&manualSourceChanged(j))controls+=flowButton('核验既有公开副本','Verify existing public copy','verify-manual-existing',id);if(['manual_action_needed','submitted','reviewing','rejected'].includes(j.status))controls+=flowButton('记录人工跟进','Record manual follow-up','manual-copy',id,'primary');if(['queued','approval_needed','ready','scheduled','manual_action_needed'].includes(j.status))controls+=flowButton('取消待办','Cancel pending','cancel-copy',id);modal(channelName(j.channel)+' · '+txt('任务详情','Task details'),`<div class="section-heading"><span class="mono">${j.id}</span>${statusBadge(j.status)}</div>${exactCopyContent(j)}${j.delay?notice(txt('计划时间','Planned time')+': '+j.delay+' · '+txt('需人工继续','Human action required')):''}${j.followupRequired?notice(txt('此副本对应旧版或已下线原文，请继续纠错或移除。','This copy refers to an older or unpublished original. Follow up with correction or removal.')):''}${j.publicUrl?`<p class="copy-link"><a href="${esc(j.publicUrl)}" target="_blank" rel="noopener noreferrer">${esc(j.publicUrl)}</a></p>`:''}${notice(txt('原型演示，不会向 NyxID 或平台发送请求。','Prototype simulation. No requests are sent to NyxID or any platform.'))}`,controls,true);};
for(const [name,fn] of [['activate-copy',activateCopy],['approve-copy',approveCopy],['cancel-copy',cancelJob]])flowHandlers[name]=id=>{const j=copyJobs.find(x=>x.id===id);if(!fn(j))return flowError('Current conditions no longer match this confirmation');closeModal();render();flowHandlers['open-copy-job'](id);};
flowHandlers['run-copy']=id=>{const j=copyJobs.find(x=>x.id===id);if(!runCopy(j,site.copyOutcome||'published'))return flowError('The account, permission or exact approval changed');closeModal();render();};
flowHandlers['copy-history']=id=>{const j=copyJobs.find(x=>x.id===id);if(j&&j.owner===state.workspace)modal(txt('完整任务历史','Complete task history'),jobHistory(j),flowButton('返回任务','Back to task','open-copy-job',id));};
flowHandlers['channel-history']=channel=>modal(channelName(channel)+' · '+txt('全部动作','All actions'),copyTasks().filter(j=>j.channel===channel).map(j=>`<div class="history-item"><div>${statusBadge(j.status)}<small>${actionLabel(j.action)} · v${j.snapshot.version} · ${j.id}</small></div>${taskButton(j)}</div>`).join(''),btn('关闭','close-modal'));
flowHandlers['manual-copy']=id=>{const j=copyJobs.find(x=>x.id===id);if(!j||j.owner!==state.workspace||!taskAuthorized(j))return;modal(channelName(j.channel)+' · '+txt('人工跟进','Manual follow-up'),`<p>${txt('记录实际平台步骤；提交和审核不等于公开。','Record the platform step. Submission and review do not mean publication.')}</p>${j.action==='remove'?notice(txt('请在平台移除以下已知链接，然后核验消失。','Remove this known URL on the platform, then verify it is no longer public.')+' '+j.publicUrl):''}<div class="form-field"><label for="manual-status">${txt('本次结果','Result')}</label><select id="manual-status">${(j.action==='remove'?['manual_action_needed','removed']:['manual_action_needed','submitted','reviewing','rejected','published']).map(s=>`<option value="${s}" ${j.status===s?'selected':''}>${txt(...statusWords[s])}</option>`).join('')}</select></div><div class="form-field"><label for="manual-url">${txt('投稿或公开链接','Submission or public URL')}</label><input id="manual-url" type="url" value="${esc(j.publicUrl||j.submissionUrl)}" ${j.action==='remove'?'readonly':''} placeholder="https://${{dev:'dev.to',medium:'medium.com',hacker:'hackernoon.com',hashnode:'chronoai.hashnode.dev'}[j.channel]}/article"></div><div class="form-field"><label for="manual-note">${txt('跟进说明','Follow-up notes')}</label><textarea id="manual-note" rows="3">${esc(j.note)}</textarea></div><label class="rights"><input type="checkbox" id="manual-verified">${txt(j.action==='remove'?'我已核验原链接不再公开。':'我已核对公开正文、账号和原文归属。',j.action==='remove'?'I verified the known URL is no longer public.':'I checked the public content, account and source attribution.')}</label><p class="form-error" id="manual-error" role="alert"></p>`,btn('取消','close-modal')+flowButton('保存跟进结果 · 演示','Save follow-up · Demo','save-manual',id,'primary'));};
flowHandlers['save-manual']=id=>{const j=copyJobs.find(x=>x.id===id);const error=recordManual(j,{status:document.getElementById('manual-status').value,url:document.getElementById('manual-url').value.trim(),note:document.getElementById('manual-note').value,sourceChecked:document.getElementById('manual-verified').checked});if(error){document.getElementById('manual-error').textContent=translateUi(txt('请检查：','Please check: ')+workflowErrorText(error));return;}closeModal();render();};
flowHandlers['verify-copy']=id=>{const j=copyJobs.find(x=>x.id===id);if(!j||j.owner!==state.workspace||!taskAuthorized(j))return;modal(txt('只读核验现有副本','Verify the existing copy'),notice(txt('只检查已经发送的结果，不会重复发送内容或创建新任务。','Only check the existing result. This never resends content or creates a new task.')),flowButton('仍未知','Still unknown','copy-still',id)+flowButton('确认未写入','Verified no write','copy-not-found',id)+flowButton('演示核验成功','Simulate verified result','copy-found',id,'primary'));};
flowHandlers['copy-still']=id=>{closeModal();};
flowHandlers['copy-not-found']=id=>{const j=copyJobs.find(x=>x.id===id);if(j?.status==='uncertain'&&j.owner===state.workspace&&taskAuthorized(j))addJobEvent(j,'failed');closeModal();render();};
flowHandlers['copy-found']=id=>{const j=copyJobs.find(x=>x.id===id);if(j?.status==='uncertain'&&j.owner===state.workspace&&taskAuthorized(j))finishCopy(j);closeModal();render();};
deliveriesPage=function(){const originals=originalJobs.filter(j=>j.owner===state.workspace&&(canPublish()||articles.find(a=>a.id===j.articleId)?.creator==='self'));let jobs=canPublish()?copyJobs.filter(j=>j.owner===state.workspace):[];jobs=jobs.filter(j=>(site.deliveryPlatform==='all'||site.deliveryPlatform===j.channel)&&(site.deliveryFilter==='all'||(site.deliveryFilter==='needs'?!['published','removed','cancelled'].includes(j.status):j.status==='published'))&&j.snapshot.savedTitle.toLowerCase().includes(site.deliveryQuery.toLowerCase()));return titleBlock('EVERY ACTION, ONE RECORD','发布与分发',txt('离开页面不会取消任务。原文与副本分别保留状态、版本和历史。','Leaving a page never cancels a task. Originals and copies retain separate states, versions and histories.'),routeButton('管理渠道','connections'))+`<h2 class="section-heading">${txt('原文任务','Original tasks')}</h2><div class="original-job-list">${originals.length?originals.slice().reverse().map(originalTaskCard).join(''):notice(txt('暂无原文任务。确认发布后会在这里持续跟进。','No original tasks yet. Confirm a publication to track it here.'))}</div><h2 class="section-heading">${txt('外部渠道任务','External channel tasks')}</h2><div class="delivery-filters"><label class="search">${icon('search')}<input id="workflow-search" type="search" aria-label="${txt('搜索任务','Search tasks')}" placeholder="${txt('搜索文章标题','Search article titles')}" value="${esc(site.deliveryQuery)}"></label>${flowButton('搜索','Search','search-jobs')}${[['all','全部任务','All tasks'],['needs','需要处理','Needs attention'],['published','已公开','Published']].map(([v,z,e])=>`<button class="btn ${site.deliveryFilter===v?'soft':''}" data-delivery-filter="${v}">${txt(z,e)}</button>`).join('')}<select id="delivery-platform" aria-label="${txt('渠道筛选','Channel filter')}"><option value="all">${txt('全部渠道','All channels')}</option>${channelCatalog.map(c=>`<option value="${c.id}" ${site.deliveryPlatform===c.id?'selected':''}>${c.name}</option>`).join('')}</select></div><div class="panel">${jobs.length?jobs.slice().reverse().map(j=>`<div class="workflow-list-row">${platform(j.channel)}<div><strong data-i18n-preserve>${esc(j.snapshot.savedTitle)}</strong><small>${j.lang.toUpperCase()} · v${j.snapshot.version} · ${actionLabel(j.action)} · ${j.account}</small></div>${statusBadge(j.status)}${taskButton(j)}</div>`).join(''):emptyState(txt('没有匹配任务','No matching tasks'),txt('可以从文章详情安排分发。','Arrange distribution from an article.'))}</div>`;};
pageRenderers.deliveries=deliveriesPage;
actions.notifications=()=>{navigate('deliveries');};
actions['refresh-distribution']=()=>render();

flowHandlers['download-copy']=id=>{const j=copyJobs.find(x=>x.id===id);if(!j||j.owner!==state.workspace||!taskAuthorized(j))return;download(`${j.channel}-${j.articleId}-${j.lang}-v${j.snapshot.version}.md`,(j.format==='excerpt'?j.excerpt:j.snapshot.savedBody)+'\n\nOriginally published at: '+j.sourceUrl+'\n');};
function manualSourceChanged(j){const a=articles.find(a=>a.id===j.articleId);return !isPublic(a,j.lang)||a.langs[j.lang].live!==j.snapshot.version;}
function reconcileManualExisting(j,{url,sourceChecked}){if(!j||j.owner!==state.workspace||!taskAuthorized(j)||!['manual_action_needed','submitted','reviewing','rejected'].includes(j.status)||!platformUrl(j.channel,url)||!sourceChecked)return false;j.followupRequired=manualSourceChanged(j);return finishCopy(j,url);}
flowHandlers['verify-manual-existing']=id=>{const j=copyJobs.find(x=>x.id===id);if(!j||!taskAuthorized(j)||j.owner!==state.workspace)return;modal(txt('核验既有公开副本','Verify an existing public copy'),notice(txt('只记录已经在平台公开的结果，不会发送或更新文章。原文已变化时，保留旧版本并标记需要纠错或移除。此独立核验交互尚需服务端接口支持。','Record only a copy that is already public on the platform. Nothing is sent or updated. If the original changed, the old version is retained and flagged for correction or removal. This independent verification flow still needs backend integration.'))+`<p>v${j.snapshot.version} · ${esc(j.account)}</p><div class="modal-field"><label for="existing-copy-url">${txt('已存在的公开链接','Existing public URL')}</label><input type="url" id="existing-copy-url" value="${esc(j.publicUrl||j.submissionUrl)}"></div><label class="rights"><input type="checkbox" id="existing-copy-verified">${txt('已核对链接、账号、正文版本与原文来源。','I verified the URL, account, content version and original attribution.')}</label><p class="form-error" id="existing-copy-error"></p>`,btn('取消','close-modal')+flowButton('记录核验 · 演示','Record verification · Demo','save-existing-copy',id,'primary'));};
flowHandlers['save-existing-copy']=id=>{const j=copyJobs.find(x=>x.id===id);if(!reconcileManualExisting(j,{url:document.getElementById('existing-copy-url').value.trim(),sourceChecked:document.getElementById('existing-copy-verified').checked})){document.getElementById('existing-copy-error').textContent=translateUi(txt('请检查公开链接和核验确认。','Check the public URL and verification confirmation.'));return;}closeModal();render();};

flowHandlers['search-jobs']=()=>{site.deliveryQuery=document.getElementById('workflow-search').value;render();};
document.addEventListener('keydown',event=>{if(event.target.id==='workflow-search'&&event.key==='Enter')flowHandlers['search-jobs']();});
